package com.chesspulseai.entity;
import com.chesspulseai.enumtype.GamePhase; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="analyses") public class PositionAnalysis { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="move_id",unique=true,nullable=false) private ChessMove move; private Integer evaluation; private Integer mateScore; @Column(length=20) private String bestMove; @Column(length=500) private String principalVariation; private int depth; private double whiteProbability; private double blackProbability; private Double drawProbability; @Enumerated(EnumType.STRING) @Column(nullable=false) private GamePhase gamePhase; @Column(length=3000) private String coachingExplanation; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @PrePersist void created(){createdAt=updatedAt=Instant.now();}@PreUpdate void updated(){updatedAt=Instant.now();}
 public ChessMove getMove(){return move;} public void setMove(ChessMove v){move=v;} public Integer getEvaluation(){return evaluation;} public void setEvaluation(Integer v){evaluation=v;} public Integer getMateScore(){return mateScore;} public void setMateScore(Integer v){mateScore=v;} public String getBestMove(){return bestMove;} public void setBestMove(String v){bestMove=v;} public String getPrincipalVariation(){return principalVariation;} public void setPrincipalVariation(String v){principalVariation=v;} public int getDepth(){return depth;} public void setDepth(int v){depth=v;} public double getWhiteProbability(){return whiteProbability;} public void setWhiteProbability(double v){whiteProbability=v;} public double getBlackProbability(){return blackProbability;} public void setBlackProbability(double v){blackProbability=v;} public Double getDrawProbability(){return drawProbability;} public void setDrawProbability(Double v){drawProbability=v;} public GamePhase getGamePhase(){return gamePhase;} public void setGamePhase(GamePhase v){gamePhase=v;} public String getCoachingExplanation(){return coachingExplanation;} public void setCoachingExplanation(String v){coachingExplanation=v;}
}
